fn diag_val(i: int, j: int) -> f64 {
    if i == j {
        1.0
    } else {
        0.0
    }
}

/// Constructs and returns an n × n identity matrix of `f64`.
#[requires(true)]
#[ensures(result.len() == n)]
#[ensures(forall(|ii: usize| ii < n ==> result[ii].len() == n))]
#[ensures(
    forall(|ii: usize, jj: usize|
        ii < n && jj < n ==>
        result[ii][jj] == diag_val(ii as int, jj as int)
    )
)]
fn identity(n: usize) -> Vec<Vec<f64>> {
    // We build up `matrix` row by row.
    let mut matrix: Vec<Vec<f64>> = Vec::with_capacity(n);

    // We'll manually turn the outer for‐loop into a while with invariants.
    let mut i: usize = 0;
    while i < n {
        // Invariants about how much of `matrix` we've built so far.
        invariant!(i <= n);
        invariant!(matrix.len() == i);
        invariant!(
            forall(|ii: usize, jj: usize|
                ii < i && jj < n ==>
                matrix[ii][jj] == diag_val(ii as int, jj as int)
            )
        );
        decreases!(n - i);

        // Build row i
        let mut row: Vec<f64> = Vec::with_capacity(n);

        // Again, turn the inner for‐loop into a while with invariants.
        let mut j: usize = 0;
        while j < n {
            invariant!(j <= n);
            invariant!(row.len() == j);
            invariant!(
                forall(|jj: usize|
                    jj < j ==>
                    row[jj] == diag_val(i as int, jj as int)
                )
            );
            decreases!(n - j);

            row.push(diag_val(i as int, j as int));
            j += 1;
        }
        // Now row.len() == n and row[j] is correct for all j < n.
        assert(row.len() == n);

        matrix.push(row);
        i += 1;
    }

    // At the end, matrix.len() == n and every entry is correct by the loop invariants.
    matrix
}

